// Generate Google Meet link with random ID
const generateMeetingId = () => {
  const chars = 'abcdefghijklmnopqrstuvwxyz';
  let result = '';
  for (let i = 0; i < 3; i++) {
    result += chars.charAt(Math.floor(Math.random() * chars.length));
    if (i < 2) result += '-';
  }
  for (let i = 0; i < 3; i++) {
    result += Math.floor(Math.random() * 10);
    if (i < 2) result += '-';
  }
  return `https://meet.google.com/${result}`;
};

const data = $input.all()[0].body;
const meetingLink = generateMeetingId();

return [
  {
    candidateId: data.candidateId,
    candidateName: data.candidateName,
    candidateEmail: data.candidateEmail,
    interviewDate: data.interviewDate,
    interviewTime: data.interviewTime,
    interviewDuration: data.interviewDuration || 60,
    timezone: data.timezone || 'EST',
    meetingLink: meetingLink,
    hrEmail: data.hrEmail || 'hr@company.com',
    interviewerName: data.interviewerName || 'Hiring Team',
    position: data.position || 'Software Engineer'
  }
]
